use super::{native_appearance_inspection as a,native_appearance_replay_study as replay,native_appearance_layer_study as layer,native_appearance_clock_study as clock,native_appearance_continuation_study as continuation};
use std::{fs,path::{Path,PathBuf},collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
pub(super) struct Fixed{pub root:PathBuf,pins:BTreeMap<String,Value>,pub used:std::cell::RefCell<BTreeMap<String,Value>>}
impl Fixed{
 pub fn new()->Self{let p:Value=serde_json::from_slice(&fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r439-appearance-snapshot.json")).unwrap()).unwrap();let root=PathBuf::from(p["candidate"]["root"].as_str().unwrap());let bytes=fs::read(root.join("manifest.json")).unwrap();assert_eq!(sha(&bytes),p["candidate"]["manifest_sha256"].as_str().unwrap().to_ascii_lowercase());let m:Value=serde_json::from_slice(&bytes).unwrap();Self{root,pins:m["files"].as_array().unwrap().iter().map(|v|(v["path"].as_str().unwrap().to_owned(),v.clone())).collect(),used:Default::default()}}
 pub fn bytes(&self,name:&str)->Vec<u8>{let p=&self.pins[name];let b=fs::read(self.root.join(name)).unwrap();assert_eq!(b.len()as u64,p["bytes"].as_u64().unwrap());assert_eq!(sha(&b),p["sha256"].as_str().unwrap().to_ascii_lowercase());self.used.borrow_mut().insert(name.to_owned(),p.clone());b}
 pub fn bank(&self,d:&a::Dependencies,trace:&Value,bank:u32)->replay::Bank{let name=format!("3476-{bank}.spr");let m=&d.members[&name];let body=layer::Asset::new(name.clone(),bank,&self.bytes(&format!("resources/{name}")),m.sha256,m.frames as usize).unwrap();let extra=|kind:&str,gfx:u32|{let name=format!("{gfx}-{bank}.spr");let hit=trace["layers"].as_array().unwrap().iter().find(|v|v["base_logical"]==734&&v["kind"]==kind).unwrap()["hits"].as_array().unwrap().iter().find(|v|v["member"]==name).unwrap();let bytes=self.bytes(&format!("resources/{name}"));assert_eq!(sha(&bytes),hit["sha256"].as_str().unwrap().to_ascii_lowercase());assert_eq!(bytes.len()as u64,hit["bytes"].as_u64().unwrap());layer::Asset::new(name,bank,&bytes,Sha256::digest(&bytes).into(),hit["frame_count"].as_u64().unwrap()as usize).unwrap()};replay::Bank{body,shadow:extra("shadow",3477),layer:extra("catalog105_layer",6260)}}
}
pub(super) fn ordinary()->clock::OrdinaryInputs{clock::OrdinaryInputs{ordinary_branch_reached:Some(true),player_global:Some(20000),queue_after_pop:Some(0),modifier_1c:Some(0),modifier_21:Some(0),action21_counter:Some(0),catalog_scaling_disabled:Some(true),frozen_external_state:Some(true),sampled_clock_ms:Some(1000)}}
pub(super) fn end()->continuation::EndInputs{continuation::EndInputs{queue_after_end:Some(0),render_player_pointer_equal:Some(false),actor_50_counter:Some(0),base_action:Some(46),idle_table_pointer_present:Some(true),queue_append_succeeds:Some(true)}}
pub(super) fn inputs()->layer::Inputs{layer::Inputs{draw_branch_reached:Some(true),actor_flags:Some(0),layer_flags:Some(0),base_shadow_route:Some(true),all_layer_pointers_present:Some(true)}}
pub(super) fn png(path:&Path,rgba:&[u8],width:u32,height:u32)->Value{let mut e=png::Encoder::new(fs::File::create(path).unwrap(),width,height);e.set_color(png::ColorType::Rgba);e.set_depth(png::BitDepth::Eight);e.write_header().unwrap().write_image_data(rgba).unwrap();json!({"path":path,"sha256":sha(&fs::read(path).unwrap()),"RGBA_sha256":sha(rgba),"dimensions":[width,height]})}
#[test]fn single_finite_attack47_replay_switches_bank88_to_end72_then_stops(){
 let fixed=Fixed::new();let d=a::nad(&fixed.bytes("resources/appearance-dependencies.nad")).unwrap();let bindings=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&bindings[3];let trace:Value=serde_json::from_slice(&fixed.bytes("appearance-layer-trace.json")).unwrap();let heading=0;let banks=BTreeMap::from([(88,fixed.bank(&d,&trace,88)),(72,fixed.bank(&d,&trace,72))]);let mut r=replay::Replay::new(true,&d,b,b,b.observed,heading,ordinary(),end()).unwrap();let mut rows=Vec::new();let mut strip=vec![0u8;1400*200*4];let mut images=Vec::new();let out=Path::new(env!("CARGO_MANIFEST_DIR")).join("target/r449-finite-player-action-cpu");fs::create_dir_all(&out).unwrap();
 for(column,expected)in [1,2,3,4,5,6,0].iter().enumerate(){let(index,bank,subframe,due)=r.next(b,b.observed).unwrap();assert_eq!(index,*expected);assert_eq!(bank,if *expected==0{72}else{88});assert_eq!(subframe,if *expected==0{0}else{(*expected-1)as u32});let pending=(index,bank,subframe,due);
  for selector in 0..3{let mut input=inputs();match selector{0=>input.all_layer_pointers_present=None,1=>input.actor_flags=None,_=>input.layer_flags=None};assert!(r.sample(b,b.observed,due,&banks[&bank],input).is_err());assert_eq!(r.next(b,b.observed).unwrap(),pending);}
  assert!(r.sample(b,b.observed,due,&banks[&if bank==72{88}else{72}],inputs()).is_err());assert_eq!(r.next(b,b.observed).unwrap(),pending);
  let frame=r.sample(b,b.observed,due,&banks[&bank],inputs()).unwrap();assert_eq!(frame.catalog_frame,index);assert_eq!(frame.bank,bank);assert_eq!(frame.subframe,subframe);assert!(!frame.sample.renderer_ready);let rgba=frame.sample.canvas.rgba();for y in 0..200{strip[(y*1400+column*200)*4..(y*1400+(column+1)*200)*4].copy_from_slice(&rgba[y*200*4..(y+1)*200*4]);}
  rows.push(json!({"catalog_frame":index,"bank":frame.bank,"subframe":frame.subframe,"dispatch_ms":frame.dispatch_ms,"next_due_ms":frame.next_due_ms,"delay_ms":frame.delay_ms,"queued_idle":frame.queued_idle,"ended":frame.ended,"members":[&banks[&bank].body.name,&banks[&bank].layer.name,&banks[&bank].shadow.name],"fragment_counts":frame.sample.fragment_count,"RGBA_sha256":sha(rgba)}));
  if frame.ended{assert_eq!(index,0);assert_eq!(frame.queued_idle,Some(49));assert_eq!(frame.delay_ms,584);assert!(r.next(b,b.observed).is_err());assert!(r.sample(b,b.observed,frame.next_due_ms,&banks[&72],inputs()).is_err());}
 }
 images.push(png(&out.join("attack47-finite-clock-body105-shadow-bank88-to-end72.png"),&strip,1400,200));assert_ne!(rows[5]["RGBA_sha256"],rows[6]["RGBA_sha256"]);
 assert!(replay::Replay::new(false,&d,b,b,b.observed,0,ordinary(),end()).is_err());let mut e=end();e.idle_table_pointer_present=None;assert!(replay::Replay::new(true,&d,b,b,b.observed,0,ordinary(),e).is_err());
 fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r449-replay-details.json"),serde_json::to_vec_pretty(&json!({"state":"SINGLE_FINITE_CONDITIONAL_ATTACK47_CLOCK_LAYER_REPLAY_END0_BANK72_STOP","rows":rows,"CPU_frames":7,"preflight_missing_condition_refusals":21,"wrong_bank_refusals":7,"images":images,"input_pins":fixed.used.into_inner(),"end0_bank72_layers_qualified_conditionally":true,"runtime_inputs_observed":false,"idle_callback_executed":false,"visible_residency_qualified":false,"renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();
}
